(async function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={audits:[],importRecord:null,verification:null,implementation:[],staging:[],defects:[],rcGates:[]};
const sorted=a=>(a||[]).slice().sort((x,y)=>Date.parse(y?.at||y?.payload?.approvedAt||y?.payload?.testedAt||y?.payload?.recordedAt||0)-Date.parse(x?.at||x?.payload?.approvedAt||x?.payload?.testedAt||x?.payload?.recordedAt||0));
const rowsByType=t=>state.audits.filter(x=>x?.type===t).map(x=>x.payload||x).filter(Boolean);const latest=rows=>JK_PHASE45.latest(rows);const hashFile=async f=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');
function badgeClass(v){return ['PASS','PLAN_APPROVED','GUARDRAIL_PASS','STAGING_PASS','IMPLEMENTATION_EVIDENCE_RECORDED','ROLLBACK_REHEARSAL_PASS','RC_APPROVED','CLOSED','REVERIFY_PASS'].includes(v)?'PASS':['FAIL','STAGING_FAIL','IMPLEMENTATION_EVIDENCE_REJECTED','RC_BLOCKED','OPEN','TRIAGED','REVERIFY_REQUIRED'].includes(v)?'FAIL':'NOT_RUN'}
function render(){const v=state.verification||{status:'NOT_IMPORTED'},coverage=JK_PHASE45.implementationCoverage(v,state.implementation),s=latest(state.staging)||{status:'NOT_RUN'},g=latest(state.rcGates)||{status:'NOT_RECORDED'};for(const [id,val] of [['phase45InputBadge',v.status],['phase45PlanBadge',v.plan?.status||'NOT_VERIFIED'],['phase45GuardrailBadge',v.guardrail?.status||'NOT_VERIFIED'],['phase45Phase44StagingBadge',v.phase44Staging?.status||'NOT_VERIFIED'],['phase45ImplBadge',coverage.complete?'COMPLETE':state.implementation.length?'INCOMPLETE':'NOT_RECORDED'],['phase45CandidateStagingBadge',s.status],['phase45RollbackBadge',s.rollbackRehearsal?.status||'NOT_RUN'],['phase45RcBadge',g.status]])if($(id)){$(id).textContent=val;$(id).className=`status ${badgeClass(val==='COMPLETE'?'PASS':val)}`};if($('phase45SourceSha'))$('phase45SourceSha').textContent=v.bundleSha256||'-';if($('phase45RequestId')){$('phase45RequestId').innerHTML='<option value="">Select authorized request</option>'+(v.requestIds||[]).map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('')};if($('phase45ImplementationList'))$('phase45ImplementationList').innerHTML=(v.requestIds||[]).map(id=>{const rec=state.implementation.find(x=>x.requestId===id&&x.accepted);return `<div class="decisionRow"><div><strong>${esc(id)}</strong><div class="note">${rec?esc(rec.builtArtifactRef):'implementation evidence required'}</div></div><span class="status ${badgeClass(rec?.status||'NOT_RECORDED')}">${esc(rec?.status||'NOT_RECORDED')}</span></div>`}).join('')||'<div class="note">No verified Phase 44 requests.</div>';if($('phase45DefectList'))$('phase45DefectList').innerHTML=state.defects.slice(0,8).map(d=>`<div class="decisionRow"><div><strong>${esc(d.defectId)} · ${esc(d.severity)}</strong><div class="note">${esc(d.summary)}</div></div><span class="status ${badgeClass(d.status)}">${esc(d.status)}</span></div>`).join('')||'<div class="note">No Phase 45 defects recorded.</div>';if($('phase45Export'))$('phase45Export').disabled=!state.importRecord}
async function load(){state.audits=sorted(await JK_STORAGE.listApprovalAudit());state.importRecord=rowsByType('phase45_phase44_audit_import_saved')[0]||null;state.verification=state.importRecord?.verification||null;state.implementation=rowsByType('phase45_implementation_evidence_saved');state.staging=rowsByType('phase45_candidate_staging_saved');state.defects=rowsByType('phase45_defect_saved');state.rcGates=rowsByType('phase45_rc_gate_saved');render()}
async function verifyBundle(){const file=$('phase45BundleFile').files?.[0];if(!file){$('phase45ImportMessage').textContent='Select a Phase 44 audit JSON.';return}try{const bundle=JSON.parse(await file.text()),sha=await hashFile(file),verification=JK_PHASE45.verifyPhase44AuditBundle(bundle,{computedSha256:sha,expectedSha256:$('phase45ExpectedSha').value}),record={format:'JK_ENG_PHASE45_PHASE44_AUDIT_IMPORT',version:'45.0',importId:verification.verificationId,phase44Bundle:bundle,phase44BundleMeta:{name:file.name,size:file.size,lastModified:file.lastModified,sha256:sha,expectedSha256:JK_PHASE45.normalizeHash($('phase45ExpectedSha').value)||null},verification,importedAt:new Date().toISOString()};await JK_STORAGE.appendApprovalAudit({type:'phase45_phase44_audit_import_saved',entityId:record.importId,payload:record});$('phase45ImportMessage').textContent=verification.status==='PASS'?'Phase 44 plan, guardrail, and actual staging verified. Implementation evidence is still required.':'Verification failed: '+verification.errors.join(', ');await load()}catch(e){$('phase45ImportMessage').textContent='Import failed: '+(e.message||e)}}
async function saveImplementation(){let sha=$('phase45ImplArtifactSha').value;const f=$('phase45ImplArtifactFile').files?.[0];if(f)sha=await hashFile(f);const rec=JK_PHASE45.recordImplementationEvidence({requestId:$('phase45RequestId').value,implementedBy:$('phase45ImplementedBy').value,evidence:$('phase45ImplEvidence').value,builtArtifactRef:$('phase45ImplArtifactRef').value||f?.name,builtArtifactSha256:sha},state.verification||{});if(!rec.accepted){$('phase45ImplMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase45_implementation_evidence_saved',entityId:rec.evidenceId,payload:rec});$('phase45ImplMessage').textContent='Implementation evidence recorded. No automatic application occurred.';await load()}
async function saveStaging(){const ids=['AUTH','DAILY_LOOP','MULTI_DEVICE_RESUME','OFFLINE_RECOVERY','ADMIN_RECOVERY','ASSET_INTEGRITY','ROLLBACK_READINESS'],cases=ids.map(id=>({id,status:$(`phase45Stage${id}Status`).value,evidence:$(`phase45Stage${id}Evidence`).value}));let csha=$('phase45CandidateSha').value,msha=$('phase45ManifestSha').value;const cf=$('phase45CandidateFile').files?.[0],mf=$('phase45ManifestFile').files?.[0];if(cf)csha=await hashFile(cf);let manifestFormat='';let manifestVersion=$('phase45ManifestVersion').value;if(mf){msha=await hashFile(mf);try{const mj=JSON.parse(await mf.text());manifestFormat=String(mj.format||'');manifestVersion=String(mj.version||manifestVersion);$('phase45ManifestVersion').value=manifestVersion}catch(_){manifestFormat='INVALID_JSON'}}const rec=JK_PHASE45.createCandidateStaging({actualStagingContext:$('phase45StagingActual').checked,stagingUrl:$('phase45StagingUrl').value,operator:$('phase45StagingOperator').value,candidateArtifactSha256:csha,assetManifestFormat:manifestFormat,assetManifestVersion:manifestVersion,assetManifestSha256:msha,cases,rollbackRehearsal:{actualRehearsal:$('phase45RollbackActual').checked,target:$('phase45RollbackTarget').value,result:$('phase45RollbackResult').value,operator:$('phase45RollbackOperator').value,evidence:$('phase45RollbackEvidence').value,restoreCandidateEvidence:$('phase45RollbackRestoreEvidence').value}},state.verification||{},state.implementation);await JK_STORAGE.appendApprovalAudit({type:'phase45_candidate_staging_saved',entityId:rec.runId,payload:rec});$('phase45StagingMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. Production deployment remains separate.`;await load()}
async function saveDefect(){const rec=JK_PHASE45.recordDefect({defectId:$('phase45DefectId').value,severity:$('phase45DefectSeverity').value,status:$('phase45DefectStatus').value,summary:$('phase45DefectSummary').value,evidence:$('phase45DefectEvidence').value});if(!rec.accepted){$('phase45DefectMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase45_defect_saved',entityId:rec.defectId,payload:rec});$('phase45DefectMessage').textContent='Defect state recorded.';await load()}
async function saveRcGate(){const preservations={processScoringPreserved:$('phase45PreserveProcess').checked,textbookReturnLoopPreserved:$('phase45PreserveTextbook').checked,evidenceMarkingPreserved:$('phase45PreserveEvidence').checked,originalRetryPreserved:$('phase45PreserveRetry').checked,nonAnxietyPacingPreserved:$('phase45PreservePacing').checked,dailyStructurePreserved:$('phase45PreserveDaily').checked},impacts={numericCountdownVisible:$('phase45ImpactCountdown').checked,bypassProcessScoring:$('phase45ImpactProcessBypass').checked,bypassTextbookReturn:$('phase45ImpactTextbookBypass').checked,dailyTimingMutation:$('phase45ImpactDailyTiming').checked,bypassEvidenceMarking:false,bypassOriginalRetry:false,automaticImplementation:false,automaticDeployment:false,automaticRollback:false,automaticPersonalizationThresholdChange:false,automaticContentApply:false};const rec=JK_PHASE45.createRCGate({operator:$('phase45RcOperator').value,evidence:$('phase45RcEvidence').value,confirmationPhrase:$('phase45RcConfirm').value,preservations,impacts,guardrailRegression:$('phase45GuardrailRegression').checked,contentApprovalMismatch:$('phase45ContentMismatch').checked,learningLoopInvariantRegression:$('phase45LoopRegression').checked,dailyStructureRegression:$('phase45DailyRegression').checked,assetIdentityFailure:$('phase45AssetIdentityFailure').checked},state.verification||{},state.implementation,latest(state.staging)||{},state.defects);await JK_STORAGE.appendApprovalAudit({type:'phase45_rc_gate_saved',entityId:rec.gateId,payload:rec});$('phase45RcMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. External v1.0.3 release remains NOT_RUN.`;await load()}
function downloadJson(payload,name){const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportAudit(){downloadJson(JK_PHASE45.buildPhase45AuditBundle({phase44BundleMeta:state.importRecord?.phase44BundleMeta||null,phase44AuditVerification:state.verification,implementationEvidence:state.implementation,candidateStagingRuns:state.staging,defects:state.defects,rcGates:state.rcGates}),`JK_ENG_Phase45_v103_Implementation_Staging_RC_${new Date().toISOString().slice(0,10)}.json`)}
await JK_AUTH.requireRole('admin');await JK_STORAGE.init();$('phase45VerifyBundle').onclick=verifyBundle;$('phase45ImplSave').onclick=saveImplementation;$('phase45StagingSave').onclick=saveStaging;$('phase45DefectSave').onclick=saveDefect;$('phase45RcSave').onclick=saveRcGate;$('phase45Export').onclick=exportAudit;await load();
})().catch(e=>{console.error(e);const el=document.getElementById('phase45ImportMessage');if(el)el.textContent=String(e.message||e)});
